// Pega todos os itens e junta em um só objeto
const merged = Object.assign({}, ...$input.all().map(i => i.json));

// Retorna apenas um item
return [{ json: merged }];

const id = Number($json.idEstagio);

const FUNIS = {
  OUTBOUND: {
    11: "Novo Lead OB",
    6: "Leads qualificados",
    7: "Contato inicial OB",
    39: "Pós Contato Phillips",
    9: "Pós Contato RM Outras Marcas",
    12: "Agendamento / reagendamento OB",
    8: "Follow-up quente",
  },

  INBOUND: {
    17: "Novo Lead IB",
    50: "Investigação Web IB",
    60: "Revisão (Temporário)",
    51: "Cadência de entrada IB",
    14: "Reaquecimento",
    15: "Agendamento IB",
    16: "Follow up quente",
  },

  RESSONANCIA_MAGNETICA: {
    3: "Reunião Comercial",
    4: "Proposta",
    5: "Negociação",
    19: "Fechamento",
    79: "Follow Up Quente",
    92: "Nutrição pós Reunião",
  },

  CONTRATO_MANUTENCAO: {
    65: "Triagem",
    66: "Ligação de Qualificação",
    67: "Apresentação",
    68: "Proposta",
    69: "Negociação",
    70: "Fechamento",
    80: "Follow Up Quente",
  },

  BOBINAS_EXAMES: {
    25: "Triagem",
    26: "Envio",
    27: "Análise Laboratório",
    28: "Negociação",
    61: "Sem Reparo",
    29: "Reparo em Execução",
    59: "Expedição",
    64: "Devolução",
    81: "Follow Up Quente",
  },

  TOMOGRAFO: {
    20: "Triagem",
    21: "Apresentação",
    22: "Proposta",
    23: "Negociação",
    24: "Fechamento",
    82: "Follow Up Quente",
  },

  ULTRASSOM: {
    71: "Triagem",
    72: "Cadência de Perfil",
    84: "Curadoria Técnica",
    73: "Apresentação",
    74: "Proposta",
    75: "Negociação",
    76: "Fechamento",
    83: "Follow Up Quente",
  },

  FOLLOW_UP_FRIO: {
    40: "F.UP OUTBOUND FRIO",
    41: "F.UP INBOUND FRIO",
    77: "F.UP BOBINAS FRIO",
  },

  CAMPANHAS_FUTURAS: {
    45: "Clínica sem RM",
    46: "Hospital",
    47: "Franquia",
    48: "Clínica Veterinária",
    52: "Unidades Centralizadas",
    85: "Clientes/Parceiros",
    91: "Fornecedores",
  },
};

let funil = "DESCONHECIDO";
let etapa = "DESCONHECIDA";

for (const [nomeFunil, etapas] of Object.entries(FUNIS)) {
  if (id in etapas) {
    funil = nomeFunil;
    etapa = etapas[id];
    break;
  }
}

return {
  ...$json,
  idEstagioNormalizado: id,
  funil,
  etapa,
};

